export const SIXTH_DAY_ADDON_ID = "sixth-day";
export const SIXTH_DAY_PRICE = "$3.00";
export const SIXTH_DAY_SKU = "megacity_sixth_day";

export function isSixthDayActive(addons?: Record<string, boolean>): boolean {
  return addons?.[SIXTH_DAY_ADDON_ID] === true;
}

export function isSDContentId(id: string): boolean {
  return id.startsWith("sd_");
}

